/** 
 * Read the incoming stream until it ends. Much of the reading will actually be done in the channel handlers as they run the XPP through the data. This method mostly handles the idle waiting for incoming data. To prevent clients from stalling channel handlers, a watch dog timer is used. Packets that take longer than the watch dog limit to read will cause the session to be closed.
 */
private void readStream() throws Exception {
  while (true) {
    try {
      Element doc=reader.parseDocument().getRootElement();
      if (doc == null) {
        return;
      }
      String tag=doc.getName();
      if ("message".equals(tag)) {
        Message packet=new Message(doc);
        packet.setFrom(session.getAddress());
        auditor.audit(packet,session);
        router.route(packet);
        session.incrementClientPacketCount();
      }
 else     if ("presence".equals(tag)) {
        Presence packet=new Presence(doc);
        packet.setFrom(session.getAddress());
        auditor.audit(packet,session);
        router.route(packet);
        session.incrementClientPacketCount();
        clearSignout=(Presence.Type.unavailable == packet.getType() ? true : false);
      }
 else     if ("iq".equals(tag)) {
        IQ packet=getIQ(doc);
        packet.setFrom(session.getAddress());
        auditor.audit(packet,session);
        router.route(packet);
        session.incrementClientPacketCount();
      }
 else {
        throw new XmlPullParserException(LocaleUtils.getLocalizedString("admin.error.packet.tag") + tag);
      }
    } catch (XmlPullParserException e) {
      throw e;
    }
  }
}
